import React, { useState } from "react";
import { Link } from "react-router-dom";

// 1. TẠO DỮ LIỆU GIẢ (MOCK DATA)
const mockProducts = [
  {
    id: 1,
    name: "Điện thoại iPhone 15 Pro Max",
    price: "29.000.000",
    category: "DienThoai",
    image: "https://via.placeholder.com/150",
    slug: "iphone-15-pro-max"
  },
  {
    id: 2,
    name: "Laptop MacBook Air M2",
    price: "25.000.000",
    category: "Laptop",
    image: "https://via.placeholder.com/150",
    slug: "macbook-air-m2"
  },
  {
    id: 3,
    name: "Điện thoại Samsung Galaxy S24",
    price: "22.000.000",
    category: "DienThoai",
    image: "https://via.placeholder.com/150",
    slug: "samsung-galaxy-s24"
  },
  {
    id: 4,
    name: "Laptop Asus Vivobook 14",
    price: "15.000.000",
    category: "Laptop",
    image: "https://via.placeholder.com/150",
    slug: "asus-vivobook-14"
  }
];

function ProductList() {
  const [searchTerm, setSearchTerm] = useState("");
  const [category, setCategory] = useState("");

  // 2. LOGIC TÌM KIẾM VÀ LỌC DỮ LIỆU TRỰC TIẾP TRÊN MẢNG GIẢ
  const filteredProducts = mockProducts.filter((item) => {
    // Kiểm tra danh mục
    const matchCategory = category === "" || item.category === category;
    // Kiểm tra từ khóa tìm kiếm (không phân biệt hoa thường)
    const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
    
    return matchCategory && matchSearch;
  });

  return (
    <div>
      <h2>Danh sách sản phẩm (Dữ liệu thử nghiệm)</h2>

      {/* --- KHU VỰC TÌM KIẾM VÀ LỌC --- */}
      <div>
        <input
          type="text"
          placeholder="Nhập tên sản phẩm cần tìm..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        
        <select
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        >
          <option value="">Tất cả danh mục</option>
          <option value="DienThoai">Điện thoại</option>
          <option value="Laptop">Laptop</option>
        </select>
      </div>

      <hr />

      {/* --- KHU VỰC HIỂN THỊ SẢN PHẨM --- */}
      <div>
        {filteredProducts.length > 0 ? (
          <ul>
            {filteredProducts.map((item) => (
              <li key={item.id}>
                <img 
                  src={item.image} 
                  alt={item.name} 
                  width="150"
                />
                <div>
                  <h3>{item.name}</h3>
                  <p>{item.price} VNĐ</p>
                  
                  {/* Link chuyển sang trang chi tiết */}
                  <Link to={`/products/${item.slug}`}>
                    <button>Xem chi tiết</button>
                  </Link>
                </div>
                <br />
              </li>
            ))}
          </ul>
        ) : (
          <p>Không tìm thấy sản phẩm nào phù hợp.</p>
        )}
      </div>
    </div>
  );
}

export default ProductList;
